INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q40','exam-fe','DMZ設計','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問40・改編】1台のファイアウォールで外部、DMZ、内部の3セグメントに分ける。外部とDMZ、DMZと内部の通信は特定プロトコルのみ許可し、外部と内部の直接通信は禁止する。WebサーバがDBのフロントエンドとして機能するWebサービスで、重要データを外部からの不正アクセスから保護する最も適切な配置はどれか。','[{"id":"a","text":"WebとDBの両方をDMZに置く"},{"id":"b","text":"WebとDBの両方を内部に置く"},{"id":"c","text":"WebをDMZ、DBを内部に置く"},{"id":"d","text":"Webを外部、DBをDMZに置く"}]','"c"','公開WebをDMZ、重要なDBを内部に置き、許可された通信のみを通す。 中文：公开Web放在DMZ，重要数据库放内网，并限制区间通信。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q47','exam-fe','分岐網羅','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問47・改編】判定A OR Bが真のとき命令を実行し、偽のとき命令を実行せず合流する。判定条件網羅（分岐網羅）を満たすテストケースの組はどれか。以下の各組は(A,B)の真偽値を表す。','[{"id":"a","text":"(偽,真)のみ"},{"id":"b","text":"(偽,真)、(真,偽)"},{"id":"c","text":"(偽,偽)、(真,真)"},{"id":"d","text":"(偽,真)、(真,偽)、(真,真)"}]','"c"','A OR Bは(偽,偽)で偽、(真,真)で真となり、両方の分岐を通る。他の選択肢には偽の判定結果がない。 中文：分支覆盖需要判定结果真和假各一次；只有(假,假)产生假。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q77','exam-fe','抜取検査とOC曲線','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問77・改編】横軸にロット不良率、縦軸にロット合格率をとるOC曲線を考える。大きさNのロットからn個抜き取り、検出した不良個数が合格判定個数c以下なら合格とする。Nとnを固定しcを0、1、2に変えたときの曲線の傾向はどれか。','[{"id":"a","text":"3本の曲線は交差せず、同じ不良率で合格率はc=0が最大、c=2が最小"},{"id":"b","text":"3本の曲線は交差せず、同じ不良率で合格率はc=2が最大、c=0が最小"},{"id":"c","text":"3本の曲線は途中で交差し、交差後はc=2が最大、c=0が最小"},{"id":"d","text":"3本の曲線は途中で交差し、交差後はc=0が最大、c=2が最小"}]','"b"','不良判定の許容数cを増やすほど、同一ロットを合格とする条件は緩くなる。同一不良率で合格率はc=0≤c=1≤c=2で、途中で逆転しない。 中文：允许的不良数越多，合格条件越宽松；同一不良率下合格率不会随c增加而降低。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
